						v_TexCoord.y * g_Texture1Resolution.w / g_Texture1Resolution.y);
	v_Bounds.x = g_Bounds.x;
	v_Bounds.y = 1.0 / (g_Bounds.y - g_Bounds.x);

#if AUDIOPROCESSING
	v_AudioPulse = CreateAudioResponse(g_AudioSpectrum16Left, g_AudioSpectrum16Right);
#endif

#if MASK == 1
